/* @author MILO-GAO(高振銘)@2020 */ package page2020.data;import java.util.LinkedHashMap;import java.util.Map;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.MessageSource;import org.springframework.stereotype.Service;import page2020.Data;import page2020.core.App;import page2020.core.Log;@Servicepublic class DataList {	private static final Logger log = LoggerFactory.getLogger(DataList.class);	@Autowired	private MessageSource messageSource;	public DataList items(Data data, String className, String fieldName) {		if (App.hasItemKey(className, fieldName)) {			LinkedHashMap<String, Object> items = new LinkedHashMap<String, Object>();			Map<String, Object> map = App.itemValue(className, fieldName);			for (String key : map.keySet()) {				String code= App.itemKey(className, fieldName, key);				if (code != null) {					items.put(key, this.messageSource.getMessage(code, null, code, null));				}			}			if (! items.isEmpty()) {				String key = String.format("%s.%s", className, fieldName);				data.add(key, items);				if (Log.data) {					log.info("items: key='" + key + "', values=" + items.toString());				}			}		}		return this;	}	public DataList items(Data data, Class<?> clazz, String fieldName) {		return this.items(data, App.className(clazz), fieldName);	}}